<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,useForm}from'@inertiajs/vue3';defineOptions({layout:AdminLayout});defineProps<{faqs:any[]}>();const create=useForm({question:'',answer:'',sort_order:0,is_active:true});function save(f:any){useForm({question:f.question,answer:f.answer,sort_order:f.sort_order,is_active:!!f.is_active}).put(`/admin/faqs/${f.id}`)}</script>
<template><Head title="CMS FAQ"/><main class="min-h-screen bg-neutral-100 p-6"><div class="mx-auto max-w-5xl"><p class="text-sm font-bold uppercase tracking-widest text-orange-600">Content CMS</p><h1 class="text-4xl font-bold">FAQ</h1><form class="card mt-8" @submit.prevent="create.post('/admin/faqs',{onSuccess:()=>create.reset()})"><h2>Tambah FAQ</h2><input v-model="create.question" placeholder="Pertanyaan" required><textarea v-model="create.answer" placeholder="Jawaban" required></textarea><input v-model="create.sort_order" type="number" min="0"><label><input v-model="create.is_active" type="checkbox"> Aktif</label><button>Tambah</button></form><section class="mt-6 space-y-4"><form v-for="faq in faqs" :key="faq.id" class="card" @submit.prevent="save(faq)"><input v-model="faq.question" required><textarea v-model="faq.answer" required></textarea><div class="flex items-center gap-4"><input v-model="faq.sort_order" type="number" min="0"><label><input v-model="faq.is_active" type="checkbox"> Aktif</label><button>Simpan</button></div></form></section></div></main></template><style scoped>.card{display:grid;gap:1rem;border-radius:1rem;background:white;padding:1.5rem}.card h2{font-size:1.25rem;font-weight:700}input,textarea{border:1px solid #d4d4d4;border-radius:.75rem;padding:.75rem}textarea{min-height:6rem}label{display:flex;align-items:center;gap:.5rem}label input{width:auto}button{border-radius:.75rem;background:#171717;color:white;padding:.7rem 1.2rem}</style>
